fn XXH32_round(mut seed: U32, mut input: U32) -> U32 {
    seed = seed.wrapping_add(input.wrapping_mul(PRIME32_2));
    seed = seed.rotate_left(13);
    seed.wrapping_mul(PRIME32_1)
}

